    private WebDriverWait wait;
    private static final String DEFAULT_DISCOUNT_CODE = System.getProperty("test.discount.code", "DISCOUNT10");

    @Before
    public void setUpWait() {
        wait = new WebDriverWait(driver, Duration.ofSeconds(10));
    }

    @Test
    public void testRemoveAppliedDiscountRestoresOriginalTotal() {
        driver.get(appUrl);

        Home homePage = new Home(driver);
        wait.until(ExpectedConditions.visibilityOfElementLocated(By.cssSelector("body")));

        List<WebElement> buyButtons = driver.findElements(By.cssSelector("button.product-card-btn, .product-item button, .btn-add-to-cart"));
        if (buyButtons.isEmpty()) {
            try {
                homePage.addToCart(1);
            } catch (Exception e) {
                Assert.fail("Precondition failed: No published product could be added to cart from the Home page.");
            }
        } else {
            homePage.addToCart(1);
        }

        homePage.openCart();
        CartSidebar cart = new CartSidebar(driver);
        cart.checkout();

        WebElement paymentOption = wait.until(ExpectedConditions.presenceOfElementLocated(
                By.cssSelector("input#discountCode, input[name='discountCode'], input[placeholder*='Discount'], #discount-code-input")
        ));
        Assert.assertNotNull("Precondition failed: Checkout is not at the payment/discount step.", paymentOption);

        WebElement totalElement = wait.until(ExpectedConditions.visibilityOfElementLocated(
                By.cssSelector("#total-amount, .order-total, .total-price, .checkout-total")
        ));
        String initialTotalText = totalElement.getText().trim();
        double undiscountedTotal = parsePrice(initialTotalText);
        Assert.assertTrue("Precondition failed: Undiscounted total must be greater than zero.", undiscountedTotal > 0.0);

        PaymentPage paymentPage = new PaymentPage(driver);
        paymentPage.setDiscountCode(DEFAULT_DISCOUNT_CODE);
        paymentPage.addDiscountCode(5);

        WebElement discountDisplay = wait.until(ExpectedConditions.visibilityOfElementLocated(
                By.cssSelector(".discount-amount, .applied-discount, #discount-row, .discount-badge")
        ));
        Assert.assertTrue("Expected discount details to be visible after applying code.", discountDisplay.isDisplayed());

        WebElement discountedTotalElement = driver.findElement(By.cssSelector("#total-amount, .order-total, .total-price, .checkout-total"));
        double discountedTotal = parsePrice(discountedTotalElement.getText().trim());
        Assert.assertTrue("Discounted total should be strictly less than the undiscounted total.", discountedTotal < undiscountedTotal);

        WebElement removeButton = wait.until(ExpectedConditions.elementToBeClickable(
                By.cssSelector("button.btn-remove-discount, #remove-discount, .remove-discount-btn, a[aria-label='Remove discount']")
        ));
        removeButton.click();

        wait.until(ExpectedConditions.invisibilityOfElementLocated(
                By.cssSelector(".discount-amount, .applied-discount, #discount-row, .discount-badge")
        ));

        WebElement discountInputField = wait.until(ExpectedConditions.visibilityOfElementLocated(
                By.cssSelector("input#discountCode, input[name='discountCode'], input[placeholder*='Discount'], #discount-code-input")
        ));
        String fieldValue = discountInputField.getAttribute("value");
        Assert.assertTrue("Discount code input field should be empty after removal.", fieldValue == null || fieldValue.trim().isEmpty());

        WebElement restoredTotalElement = wait.until(ExpectedConditions.visibilityOfElementLocated(
                By.cssSelector("#total-amount, .order-total, .total-price, .checkout-total")
        ));
        double restoredTotal = parsePrice(restoredTotalElement.getText().trim());
        Assert.assertEquals("Restored total should equal the recorded undiscounted total.", undiscountedTotal, restoredTotal, 0.01);
    }

